-- V12: catálogo de subrutas, paraderos y geometrías desde datos de la app
-- Reemplaza datos previos de rutas en las nuevas tablas y limpia paraderos seed antiguos.

BEGIN;

-- Subrutas concretas (unidad operativa), agrupadas por línea general
CREATE TABLE IF NOT EXISTS subruta (
    id SERIAL PRIMARY KEY,
    linea_codigo VARCHAR(20) NOT NULL,
    linea_nombre VARCHAR(100) NOT NULL,
    codigo VARCHAR(50) NOT NULL,
    nombre VARCHAR(255) NOT NULL,
    operador VARCHAR(150),
    color_hex VARCHAR(9),
    route_id_ida VARCHAR(30),
    route_id_retorno VARCHAR(30),
    nombre_retorno VARCHAR(255),
    activa BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT uq_subruta_codigo UNIQUE (codigo),
    CONSTRAINT uq_subruta_route_ida UNIQUE (route_id_ida)
);

CREATE INDEX IF NOT EXISTS idx_subruta_linea_codigo ON subruta(linea_codigo);
CREATE INDEX IF NOT EXISTS idx_subruta_route_ida ON subruta(route_id_ida);
CREATE INDEX IF NOT EXISTS idx_subruta_route_retorno ON subruta(route_id_retorno);

-- Paraderos por subruta y sentido (IDA/RETORNO)
CREATE TABLE IF NOT EXISTS subruta_paradero (
    id BIGSERIAL PRIMARY KEY,
    subruta_id INT NOT NULL REFERENCES subruta(id) ON DELETE CASCADE,
    sentido VARCHAR(10) NOT NULL CHECK (sentido IN ('IDA','RETORNO')),
    externo_id VARCHAR(50),
    nombre VARCHAR(255),
    latitud DOUBLE PRECISION NOT NULL,
    longitud DOUBLE PRECISION NOT NULL,
    orden INT NOT NULL,
    distrito VARCHAR(120),
    CONSTRAINT uq_subruta_paradero UNIQUE (subruta_id, sentido, orden)
);

CREATE INDEX IF NOT EXISTS idx_subruta_paradero_subruta ON subruta_paradero(subruta_id, sentido, orden);

-- Geometría (trazado) por subruta y sentido como JSON array [[lat,lon],...]
CREATE TABLE IF NOT EXISTS subruta_geometria (
    id BIGSERIAL PRIMARY KEY,
    subruta_id INT NOT NULL REFERENCES subruta(id) ON DELETE CASCADE,
    sentido VARCHAR(10) NOT NULL CHECK (sentido IN ('IDA','RETORNO')),
    puntos_json TEXT NOT NULL,
    CONSTRAINT uq_subruta_geometria UNIQUE (subruta_id, sentido)
);

CREATE INDEX IF NOT EXISTS idx_subruta_geometria_subruta ON subruta_geometria(subruta_id, sentido);


-- Reemplazar datos previos en tablas nuevas
DELETE FROM subruta_geometria;
DELETE FROM subruta_paradero;
DELETE FROM subruta;

-- Limpiar paraderos seed antiguos (punto_control) solo si no tienen cumplimientos referenciados.
-- En despliegues con registro_cumplimiento existente, esos puntos se conservan.
DELETE FROM punto_control pc
WHERE NOT EXISTS (SELECT 1 FROM registro_cumplimiento rc WHERE rc.punto_control_id = pc.id);

-- Líneas generales (padres): asegurar C2-C11 sin romper referencias existentes
UPDATE linea SET corredor = COALESCE(corredor, 'Transcayma'), color_hex = '#E53935' WHERE nombre = 'Línea C2';
UPDATE linea SET corredor = COALESCE(corredor, 'C3'), color_hex = '#1E88E5' WHERE nombre = 'Línea C3';
UPDATE linea SET corredor = COALESCE(corredor, 'C4'), color_hex = '#43A047' WHERE nombre = 'Línea C4';
UPDATE linea SET corredor = COALESCE(corredor, 'C5'), color_hex = '#FB8C00' WHERE nombre = 'Línea C5';
UPDATE linea SET corredor = COALESCE(corredor, 'C6'), color_hex = '#8E24AA' WHERE nombre = 'Línea C6';
UPDATE linea SET corredor = COALESCE(corredor, 'C7'), color_hex = '#00ACC1' WHERE nombre = 'Línea C7';
UPDATE linea SET corredor = COALESCE(corredor, 'C8'), color_hex = '#D81B60' WHERE nombre = 'Línea C8';
UPDATE linea SET corredor = COALESCE(corredor, 'C9'), color_hex = '#546E7A' WHERE nombre = 'Línea C9';
UPDATE linea SET corredor = COALESCE(corredor, 'C10'), color_hex = '#FDD835' WHERE nombre = 'Línea C10';
UPDATE linea SET corredor = COALESCE(corredor, 'C11'), color_hex = '#6D4C41' WHERE nombre = 'Línea C11';

